-            return m_outputEncoding;
-        }
-
-        public void setOutputEncoding(String outputEncoding) {
-            if ($assert.ENABLED) $assert.ASSERT (outputEncoding != null, "null input: outputEncoding");
-            this.m_outputEncoding = outputEncoding;
-        }
     } // end of nested class


